fun localized(source: String, language: String): String = when (language) { "en" -> english[source] ?: source; "es" -> spanish[source] ?: source; else -> source }
@Composable fun T(source: String, modifier: Modifier = Modifier, style: TextStyle = androidx.compose.material3.LocalTextStyle.current, color: Color = Color.Unspecified, fontWeight: androidx.compose.ui.text.font.FontWeight? = null) { Text(localized(source, LocalAppLanguage.current), modifier = modifier, style = style, color = color, fontWeight = fontWeight) }